modified_existing_code_delta.old_guard:
const SHA=/^[a-f0-9]{40}$/;
export function backupClaimRef(freshnessKey){
 if(typeof freshnessKey!=='string'||!/^20\d\d-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d{1,9})?Z$/.test(freshnessKey)||
  !Number.isFinite(Date.parse(freshnessKey)))
  throw Error('Current observed database-write UTC timestamp required for durable backup claim');

modified_existing_code_delta.new_guard:
const SHA=/^[a-f0-9]{40}$/;
const VALID_UTC=/^20\d{2}-(?:0[1-9]|1[0-2])-(?:0[1-9]|[12]\d|3[01])T(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d{1,9})?Z$/;
export function backupClaimRef(freshnessKey){
 const epoch=typeof freshnessKey==='string'?Date.parse(freshnessKey):NaN;
 if(!VALID_UTC.test(freshnessKey||'')||!Number.isFinite(epoch)||
  new Date(epoch).toISOString().slice(0,19)!==freshnessKey.slice(0,19))
  throw Error('Current observed database-write UTC timestamp required for durable backup claim');

modified_existing_code_delta.added_test:
test('backup claim rejects impossible calendar dates, retains valid leap day and fractions',()=>{
 for(const invalid of ['2026-02-31T12:00:00Z','2026-11-31T12:00:00Z',
  '2026-04-31T12:00:00Z','2026-13-01T12:00:00Z','2026-00-01T12:00:00Z',
  '2026-11-02T24:00:00Z','2026-11-02T01:60:00Z','2026-11-02T01:00:60Z'])
  assert.throws(()=>backupClaimRef(invalid),/database-write UTC timestamp required/);
 assert.match(backupClaimRef('2024-02-29T12:00:00.000000001Z'),
  /^refs\/heads\/dic-backup-claims\/[a-f0-9]{40}$/);
});
